from typing import List, Dict, Any
import pandas as pd
import sys

class DataContractViolation(Exception):
    """Excepcion levantada para activar el Circuit Breaker de calidad de datos."""
    pass

def validate_data_contract(df: pd.DataFrame) -> bool:
    errors = []

    # Regla 1: Columnas requeridas presentes
    required_columns = {"id", "user_id", "amount", "timestamp"}
    missing_cols = required_columns - set(df.columns)
    if missing_cols:
        errors.append(f"Violacion de Esquema: Faltan columnas obligatorias: {missing_cols}")

    # Regla 2: Porcentaje de nulos en user_id menor al 1%
    if "user_id" in df.columns:
        null_ratio = df["user_id"].isnull().mean()
        if null_ratio > 0.01:
            errors.append(f"Violacion de Calidad: Tasa de nulos en 'user_id' es {null_ratio:.2%}, excede el maximo del 1.0%")

    # Regla 3: Montos estrictamente mayores a 0
    if "amount" in df.columns:
        negative_count = (df["amount"] <= 0).sum()
        if negative_count > 0:
            errors.append(f"Violacion de Integridad: Se encontraron {negative_count} registros con montos <= 0")

    if errors:
        print("\n[CIRCUIT BREAKER ACTIVADO] Deteniendo pipeline por violaciones criticas:")
        for err in errors:
            print(f"  - {err}")
        raise DataContractViolation("El lote de datos ha sido rechazado por el contrato de calidad.")

    print("[CONTRATO VALIDO] El dataset cumple con todas las expectativas de calidad.")
    return True

# 1. Prueba con Lote Valido
print("--- EVALUANDO LOTE 1 (DATOS SALUDABLES) ---")
df_healthy = pd.DataFrame([
