print("\n--- EVALUANDO LOTE 2 (DATOS CORRUPTOS UPSTREAM) ---")
df_corrupted = pd.DataFrame([
    {"id": 4, "user_id": None, "amount": -500.0, "timestamp": "2026-09-28T12:03:00"},
